import{_ as i,l as s,o as e,c as n,v as r,p as l,x as t,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"谓词下推","description":"","frontmatter":{"title":"谓词下推","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/predicate-pushdown.md","filePath":"cs/predicate-pushdown.md","lastUpdated":1789023840000}'),c={name:"cs/predicate-pushdown.md"};function p(u,a,_,B,m,A){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="谓词下推" tabindex="-1">谓词下推 <a class="header-anchor" href="#谓词下推" aria-label="Permalink to &quot;谓词下推&quot;">​</a></h1><div class="epigraph"><p>能在扫描或第一次连接前就丢掉的行，不要拖到树顶再过滤；下推是改写里最常用的一条。</p><footer>—— 据 Ullman 对选择下推；Chaudhuri；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/query-rewrite">上一课</a>说先用代数律把树变瘦。本课不重列结合律。缺口是那一课最重要的实例：把 <code>WHERE</code>/<code>HAVING</code> 能下到的谓词推向叶子或更低的连接，使中间基数按<a href="/cs/histogram-card">直方图</a>变小。外连接与相关子查询会挡住部分下推。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>查询改写留下「下推与结合」。若优化器只交换连接顺序、不把选择贴到扫描，索引与堆扫描仍读全集。谓词下推：选择穿过投影（保留需要的列）、穿过内连接。缺口是<strong>这一条律的机制与挡板</strong>，不是代价搜索本身。</p><p><span class="marginnote">下推到存储引擎（仅读需要的列与行）是同一思想的物理版。易失函数、随机() 不能无约束下推。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从树顶收集合取项，按引用的属性集合贴到最深仍合法的节点。不能穿过改变 NULL 填充的外连接侧。物化视图匹配是另一类改写，后课视图。本课不把全部 IDB 规则写成 Datalog 教材。</p>',8)),(e(),l(E,null,{default:t(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOP%5B%22%E9%A1%B6%E5%B1%82%E8%BF%87%E6%BB%A4%22%5D%20--%3E%20PUSH%5B%22%E6%8E%A8%E5%90%91%E6%89%AB%E6%8F%8F%E6%88%96%E4%BD%8E%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20PUSH%20--%3E%20SMALL%5B%22%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%E5%8F%98%E5%B0%8F%22%5D%0A%20%20BLOCK%5B%22%E5%A4%96%E8%BF%9E%E6%8E%A5%20%2F%20%E6%98%93%E5%A4%B1%E5%87%BD%E6%95%B0%22%5D%20--%3E%20STOP%5B%22%E5%81%9C%E5%9C%A8%E6%8C%A1%E6%9D%BF%E4%B9%8B%E4%B8%8A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下推直接兑现<a href="/cs/algebra-reorder">选择投影连接的顺序</a>里画过的那棵瘦树。物理上，叶子扫描可以变成索引条件。语义在内连接与无 NULL 坑时与原 SQL 一致；挡板存在是为了不把 unknown 变成错行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把谓词下推到另一台分片节点的网络协议写完（后课分片）。模式太宽导致的更新异常，下一课范式。</p><p>后课默认：过滤尽量靠近数据。表太宽是设计问题，不是再下推一次能修好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选择尽量下推以减小中间结果。</li><li>外连接与易失性是挡板。</li><li>范式与分解下一课。</li><li>出处：Ullman；Chaudhuri；Ramakrishnan and Gehrke。</li></ul>',7))])}const T=i(c,[["render",p]]);export{P as __pageData,T as default};
